export { protoPathToFormPath } from './proto-error-path.js';
export type { FlattenProtoOneofs } from './proto-paths.js';
export { createProtoResolver } from './proto-resolver.js';
export {
  type ConnectErrorContext,
  type UseProtoFormOptions,
  type UseProtoFormReturn,
  useProtoForm,
  useProtoFormDefaults,
} from './use-proto-form.js';

import type { DescMessage } from '@bufbuild/protobuf';
import { protoPathToFormPath as mapProtoPathToFormPath } from '@/registry/base-nova/protoform/lib/protobuf-provider/proto-error-path.js';

export function protoPathToFormPath(schema: DescMessage, serverPath: string): string | null {
  return mapProtoPathToFormPath(schema, serverPath);
}

import type { JsonValue } from '@bufbuild/protobuf';

export type ProtoFormValues<T> = T extends { $typeName: 'google.protobuf.Timestamp' | 'google.protobuf.Duration' }
  ? string
  : T extends { $typeName: 'google.protobuf.FieldMask' }
    ? string[]
    : T extends { $typeName: 'google.protobuf.Any' }
      ? { typeUrl?: string; valueBase64?: string }
      : T extends { $typeName: 'google.protobuf.Struct' | 'google.protobuf.Value' | 'google.protobuf.ListValue' }
        ? JsonValue
        : T extends bigint | Uint8Array
          ? string
          : T extends (infer Item)[]
            ? ProtoFormValues<Item>[]
            : T extends object
              ? string extends keyof T
                ? { key: string; value: ProtoFormValues<T[string]> }[] | { [key: string]: ProtoFormValues<T[string]> }
                : true extends IsProtoOneof<T>
                  ? { [Key in keyof FlattenOneof<T>]: ProtoFormValues<FlattenOneof<T>[Key]> }
                  : { [Key in keyof T as Key extends `$${string}` ? never : Key]: ProtoFormValues<T[Key]> }
              : T;

type IsProtoOneof<T> = T extends { case: string; value: infer _V }
  ? { case: undefined; value?: undefined } extends T
    ? true
    : false
  : false;

type UnionToIntersection<U> = (U extends unknown ? (k: U) => void : never) extends (k: infer I) => void ? I : never;

interface FlattenOneof<T> {
  case: T extends { case: infer C } ? C : never;
  value: UnionToIntersection<T extends { case: string; value: infer V } ? V : never> | undefined;
}

export type FlattenProtoOneofs<T> = T extends (infer U)[]
  ? FlattenProtoOneofs<U>[]
  : T extends object
    ? true extends IsProtoOneof<T>
      ? { [K in keyof FlattenOneof<T>]: FlattenProtoOneofs<FlattenOneof<T>[K]> }
      : { [K in keyof T]: FlattenProtoOneofs<T[K]> }
    : T;

import type { DescMessage, MessageShape, MessageValidType } from '@bufbuild/protobuf';
import { type FieldError, type FieldErrors, get, type Resolver, type ResolverOptions, set } from 'react-hook-form-v8';
import type { FormValues } from '@/registry/base-nova/protoform/lib/core/index.js';
import {
  PROTO_FORM_ROOT_ERROR_KEY,
  type ProtoFormOptions,
  validateFormValuesAgainstProtoSchema,
} from '@/registry/base-nova/protoform/lib/protobuf-provider/hook-runtime.js';
import {
  humanizeValidationError,
  isGenericValidationMessage,
} from '@/registry/base-nova/protoform/lib/protobuf-provider/humanize-validation-error.js';
import { createDescriptorAwareStandardSchema } from '@/registry/base-nova/protoform/lib/protobuf-provider/validation-schema.js';

type ProtoResolver<Desc extends DescMessage> = (
  values: FormValues,
  context: unknown,
  options: ResolverOptions<FormValues>,
  currentSource?: MessageShape<Desc>
) => ReturnType<Resolver<FormValues, unknown, MessageValidType<Desc>>>;

function validateFieldNatively(ref: HTMLInputElement, path: string, errors: Record<string, FieldError>) {
  if (!('reportValidity' in ref)) {
    return;
  }
  const error = get(errors, path) as FieldError | undefined;
  ref.setCustomValidity(error?.message ?? '');
  ref.reportValidity();
}

function validateFieldsNatively(errors: Record<string, FieldError>, options: ResolverOptions<FormValues>) {
  for (const [path, field] of Object.entries(options.fields)) {
    if (field?.ref && 'reportValidity' in field.ref) {
      validateFieldNatively(field.ref as HTMLInputElement, path, errors);
      continue;
    }
    for (const ref of field?.refs ?? []) {
      validateFieldNatively(ref, path, errors);
    }
  }
}

function isFieldArrayRoot(names: string[], path: string): boolean {
  const escapedPath = path.replace(/[[\]]/gu, '').replace(/[.*+?^${}()|[\]\\]/gu, '\\$&');
  return names.some((name) => name.replace(/[[\]]/gu, '').match(`^${escapedPath}\\.\\d+`));
}

function toNestErrors(
  flatErrors: Record<string, FieldError>,
  options: ResolverOptions<FormValues>
): FieldErrors<FormValues> {
  if (options.shouldUseNativeValidation === true) {
    validateFieldsNatively(flatErrors, options);
  }
  const nestedErrors: FieldErrors<FormValues> = {};
  for (const path of Object.keys(flatErrors)) {
    const field = get(options.fields, path) as ResolverOptions<FormValues>['fields'][string] | undefined;
    const error = Object.assign(flatErrors[path] ?? {}, {
      ref: field?.refs?.[0] ?? field?.ref,
    });
    if (isFieldArrayRoot(options.names ?? Object.keys(flatErrors), path)) {
      const fieldArrayError = { ...(get(nestedErrors, path) ?? {}) };
      set(fieldArrayError, 'root', error);
      set(nestedErrors, path, fieldArrayError);
    } else {
      set(nestedErrors, path, error);
    }
  }
  return nestedErrors;
}

export function createProtoResolver<Desc extends DescMessage>(
  desc: Desc,
  options: ProtoFormOptions = {},
  source?: MessageShape<Desc>
): ProtoResolver<Desc> {
  const standardSchema = createDescriptorAwareStandardSchema(desc, options);

  return async (values, _context, resolverOptions, currentSource = source) => {
    const validationResult = await validateFormValuesAgainstProtoSchema(
      desc,
      values,
      standardSchema,
      options,
      currentSource
    );

    if (!validationResult.issues) {
      if (resolverOptions.shouldUseNativeValidation) {
        validateFieldsNatively({}, resolverOptions);
      }
      return {
        errors: {},
        values: validationResult.value,
      };
    }

    const rawErrors: Record<string, { message: string; isGeneric: boolean }> = {};
    for (const issue of validationResult.issues) {
      if (issue.path.length === 0) {
        continue;
      }
      const path = issue.path.join('.');
      const generic = isGenericValidationMessage(issue.message);
      const existing = rawErrors[path];
      if (!existing) {
        rawErrors[path] = { isGeneric: generic, message: issue.message };
      } else if (existing.isGeneric && !generic) {
        rawErrors[path] = { isGeneric: false, message: issue.message };
      }
    }

    const flatErrors: Record<string, { message: string; type: string }> = {};
    for (const [path, entry] of Object.entries(rawErrors)) {
      flatErrors[path] = {
        message: humanizeValidationError(entry.message, options.formatMessage),
        type: 'validation',
      };
    }

    const nestedErrors = toNestErrors(flatErrors, resolverOptions);
    const rootMessages: string[] = [];
    for (const issue of validationResult.issues) {
      if (issue.path.length === 0) {
        rootMessages.push(humanizeValidationError(issue.message, options.formatMessage));
      }
    }

    const [rootMessage] = rootMessages;
    if (rootMessage !== undefined && rootMessage !== '') {
      const errors = Object.assign(nestedErrors, {
        root: {
          message: rootMessages.join('\n'),
          type: 'validation',
        },
        [PROTO_FORM_ROOT_ERROR_KEY]: {
          message: rootMessage,
          type: 'validation',
        },
      });
      return {
        errors,
        values: {},
      };
    }

    return {
      errors: nestedErrors,
      values: {},
    };
  };
}

import { create, type DescMessage, isMessage, type MessageInitShape, type MessageShape } from '@bufbuild/protobuf';
import type { FieldMask } from '@bufbuild/protobuf/wkt';
import { ConnectError } from '@connectrpc/connect';
import { useRef, useState } from 'react';
import {
  type FieldPath,
  type Path,
  type SetValueConfig,
  type UseFormProps,
  type UseFormReturn,
  useForm,
} from 'react-hook-form-v8';
import { createUpdateMask as createDirtyUpdateMask } from '@/registry/base-nova/protoform/lib/protobuf-provider/field-mask.js';
import {
  type ConnectErrorContext,
  extractConnectErrorContext,
  extractFieldViolations,
} from '@/registry/base-nova/protoform/lib/protobuf-provider/format-error.js';
import {
  formValuesToProto,
  type ProtoConversionOptions,
  type ProtoFormOptions,
  protoToFormValues,
} from '@/registry/base-nova/protoform/lib/protobuf-provider/hook-runtime.js';
import { humanizeServerFieldError } from '@/registry/base-nova/protoform/lib/protobuf-provider/humanize-validation-error.js';

import { protoPathToFormPath } from './proto-error-path.js';
import type { ProtoFormValues } from './proto-paths.js';
import { createProtoResolver } from './proto-resolver.js';

export type { ConnectErrorContext } from '@/registry/base-nova/protoform/lib/protobuf-provider/format-error.js';

type FormShape<Desc extends DescMessage> = {
  [Key in keyof Omit<MessageShape<Desc>, '$typeName' | '$unknown'>]: ProtoFormValues<MessageShape<Desc>[Key]>;
};

type NestedErrors<T> = {
  [K in keyof T]?: T[K] extends object ? NestedErrors<T[K]> & { message?: string } : { message?: string };
};

export interface UseProtoFormOptions<Desc extends DescMessage>
  extends Omit<UseFormProps<FormShape<Desc>>, 'resolver' | 'defaultValues'> {
  defaultValues?:
    | UseFormProps<FormShape<Desc>>['defaultValues']
    | MessageShape<Desc>
    | (() => Promise<MessageShape<Desc>>);
  emptyRepeatedStringPolicies?: ProtoConversionOptions['emptyRepeatedStringPolicies'];
  formatMessage?: ProtoFormOptions['formatMessage'];
  serverPathPrefix?: string;
  serverPathPrefixes?: readonly string[];
}

export type UseProtoFormReturn<Desc extends DescMessage> = Omit<UseFormReturn<FormShape<Desc>>, 'reset'> & {
  reset: (
    values?: Parameters<UseFormReturn<FormShape<Desc>>['reset']>[0] | MessageShape<Desc>,
    options?: Parameters<UseFormReturn<FormShape<Desc>>['reset']>[1]
  ) => void;
  createMessage: (values?: FormShape<Desc>) => MessageShape<Desc>;
  createUpdateMask: () => FieldMask;
  setOneofValue: (path: string, oneofCase: string, value: unknown, options?: SetValueConfig) => void;
  getNestedErrors: <T = Record<string, { message?: string }>>(path: string) => NestedErrors<T> | undefined;
  setServerErrors: (error: unknown) => {
    context: ConnectErrorContext;
    handled: boolean;
    unmapped: { field: string; description: string }[];
  };
  serverErrorContext: ConnectErrorContext | undefined;
  clearServerErrorContext: () => void;
};

export function useProtoForm<Desc extends DescMessage>(
  schema: Desc,
  options?: UseProtoFormOptions<Desc>
): UseProtoFormReturn<Desc> {
  const {
    emptyRepeatedStringPolicies,
    formatMessage,
    serverPathPrefix,
    serverPathPrefixes = [],
    mode = 'onChange',
    ...rest
  } = options ?? {};
  const conversionOptions: ProtoFormOptions = {
    emptyRepeatedStringPolicies,
    formatMessage,
  };
  const pathPrefixes =
    serverPathPrefix !== undefined && serverPathPrefix !== ''
      ? [serverPathPrefix, ...serverPathPrefixes]
      : serverPathPrefixes;
  const sourceMessage = useRef(isMessage(rest.defaultValues, schema) ? rest.defaultValues : undefined);
  const normalizeValues = (values: unknown) =>
    isMessage(values, schema) ? (protoToFormValues(schema, values) as FormShape<Desc>) : (values as FormShape<Desc>);
  const suppliedDefaults = rest.defaultValues;
  const normalizedDefaults = suppliedDefaults === undefined ? undefined : normalizeValues(suppliedDefaults);
  const defaultValues =
    typeof suppliedDefaults === 'function'
      ? async () => {
          const values = await suppliedDefaults();
          if (isMessage(values, schema)) {
            sourceMessage.current = values;
          }
          return normalizeValues(values);
        }
      : normalizedDefaults;

  const resolver = createProtoResolver(schema, conversionOptions);
  const resolveValues: typeof resolver = (values, context, resolverOptions) =>
    resolver(values, context, resolverOptions, sourceMessage.current);
  const form = useForm({
    ...rest,
    defaultValues,
    mode,
    resolver: resolveValues,
  } as unknown as UseFormProps<FormShape<Desc>>) as UseFormReturn<FormShape<Desc>>;
  const { defaultValues: initialValues, dirtyFields, errors: formErrors } = form.formState;
  const reset: UseProtoFormReturn<Desc>['reset'] = (values, keepStateOptions) => {
    const next = typeof values === 'function' ? values(form.getValues()) : values;
    if (isMessage(next, schema)) {
      sourceMessage.current = next;
    }
    form.reset(next === undefined ? undefined : normalizeValues(next), keepStateOptions);
  };
  const createMessage = (values?: FormShape<Desc>): MessageShape<Desc> => {
    const raw = values ?? form.getValues();
    return formValuesToProto(schema, raw, sourceMessage.current, conversionOptions);
  };

  const createUpdateMask = (): FieldMask => createDirtyUpdateMask(schema, dirtyFields, form.getValues(), initialValues);

  const setOneofValue = (path: string, oneofCase: string, value: unknown, setValueOptions?: SetValueConfig) => {
    const current = form.getValues(path as Path<FormShape<Desc>>);
    const isOneof = current === undefined || current === null || (typeof current === 'object' && 'case' in current);
    if (!isOneof) {
      throw new Error(
        `setOneofValue("${path}"): target is not a oneof field. ` +
          'Expected { case, value } shape. Use setValue() for regular fields.'
      );
    }
    const prev = current as { case?: string; value?: unknown } | undefined;
    if (prev?.case !== undefined && prev?.case !== '' && prev.case !== oneofCase) {
      form.setValue(path as Path<FormShape<Desc>>, { case: '', value: {} } as never);
    }
    form.setValue(path as Path<FormShape<Desc>>, { case: oneofCase, value } as never, {
      shouldDirty: true,
      shouldValidate: true,
      ...setValueOptions,
    });
  };

  const getNestedErrors = <T = Record<string, { message?: string }>>(path: string): NestedErrors<T> | undefined => {
    const segments = path.split('.');
    let current: unknown = formErrors;
    for (const segment of segments) {
      if (current === undefined || current === null) {
        return;
      }
      current = (current as Record<string, unknown>)[segment];
    }
    return current as NestedErrors<T> | undefined;
  };

  const [serverErrorContext, setServerErrorContext] = useState<ConnectErrorContext | undefined>(undefined);
  const clearServerErrorContext = () => setServerErrorContext(undefined);

  const setServerErrors = (error: unknown) => {
    const context = extractConnectErrorContext(error);
    setServerErrorContext(context);

    if (!(error instanceof ConnectError)) {
      return {
        context,
        handled: false,
        unmapped: [] as { field: string; description: string }[],
      };
    }
    const unmapped: { field: string; description: string }[] = [];
    let handled = false;
    const fieldMessages = new Map<string, string[]>();
    for (const violation of extractFieldViolations(error)) {
      const bare = stripPrefix(violation.field, pathPrefixes);
      const formPath = protoPathToFormPath(schema, bare);
      if (!(formPath !== null && formPath !== '')) {
        unmapped.push(violation);
        continue;
      }
      fieldMessages.set(formPath, [
        ...(fieldMessages.get(formPath) ?? []),
        humanizeServerFieldError(violation.description),
      ]);
    }
    for (const [path, messages] of fieldMessages) {
      form.setError(
        path as FieldPath<FormShape<Desc>>,
        {
          message: messages[0] ?? '',
          type: 'server',
          types: Object.fromEntries(messages.map((message, index) => [String(index), message])),
        },
        handled ? undefined : { shouldFocus: true }
      );
      handled = true;
    }
    return { context, handled, unmapped };
  };

  return {
    ...form,
    reset,
    clearServerErrorContext,
    createMessage,
    createUpdateMask,
    getNestedErrors,
    serverErrorContext,
    setOneofValue,
    setServerErrors,
  };
}

export function useProtoFormDefaults<Desc extends DescMessage>(
  schema: Desc,
  init?: MessageInitShape<Desc>
): MessageShape<Desc> {
  return create(schema, init ?? ({} as MessageInitShape<Desc>));
}

function stripPrefix(field: string, prefixes: readonly string[]): string {
  for (const prefix of prefixes) {
    if (!prefix) {
      continue;
    }
    const withDot = `${prefix}.`;
    if (field.startsWith(withDot)) {
      return field.slice(withDot.length);
    }
  }
  return field;
}
